import{_ as s,o as a,c as e,a as n}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"YugabyteDB分布式SQL架构详解学习笔记","description":"","frontmatter":{},"headers":[],"relativePath":"data/database/relational/distributed/yugabytedb.md","filePath":"data/database/relational/distributed/yugabytedb.md"}'),r={name:"data/database/relational/distributed/yugabytedb.md"};function l(o,t,i,g,h,d){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="yugabytedb分布式sql架构详解学习笔记" tabindex="-1">YugabyteDB分布式SQL架构详解学习笔记 <a class="header-anchor" href="#yugabytedb分布式sql架构详解学习笔记" aria-label="Permalink to &quot;YugabyteDB分布式SQL架构详解学习笔记&quot;">​</a></h1><h2 id="一、核心设计哲学与架构总览" tabindex="-1">一、核心设计哲学与架构总览 <a class="header-anchor" href="#一、核心设计哲学与架构总览" aria-label="Permalink to &quot;一、核心设计哲学与架构总览&quot;">​</a></h2><p>YugabyteDB的设计哲学独特而明确：<strong>在分布式环境下提供完整的PostgreSQL兼容性和强一致性ACID事务，同时避免传统分布式数据库的复杂性与性能折衷</strong>。其核心架构围绕“两层架构”展开，实现了SQL计算层与分布式存储层的清晰分离与高效协同。</p><p>为了直观理解其工作方式，下图展示了YugabyteDB的整体架构及核心组件间的协作流程：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">flowchart LR</span></span>
<span class="line"><span class="__shiki_140thh">    subgraph Client_Layer [客户端/应用层]</span></span>
<span class="line"><span class="__shiki_140thh">        App[&quot;应用程序&lt;br&gt;（使用PostgreSQL协议）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    subgraph YB_TServer_Layer [YB-TServer 数据与计算层]</span></span>
<span class="line"><span class="__shiki_140thh">        TServer1[&quot;YB-TServer&lt;br&gt;（节点1）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        TServer2[&quot;YB-TServer&lt;br&gt;（节点2）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        TServer3[&quot;YB-TServer&lt;br&gt;（节点3）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    subgraph DocDB_Storage [DocDB 分布式存储引擎]</span></span>
<span class="line"><span class="__shiki_140thh">        Tablet1[&quot;Tablet/分片&lt;br&gt;（Leader）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        Tablet2[&quot;Tablet/分片&lt;br&gt;（Follower）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        Tablet3[&quot;Tablet/分片&lt;br&gt;（Follower）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    subgraph YB_Master_Layer [YB-Master 元数据与协调层]</span></span>
<span class="line"><span class="__shiki_140thh">        Master1[&quot;YB-Master&lt;br&gt;（Leader）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        Master2[&quot;YB-Master&lt;br&gt;（Follower）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    App -- &quot;1. SQL查询请求&quot; --&gt; YB_TServer_Layer</span></span>
<span class="line"><span class="__shiki_140thh">    YB_TServer_Layer -- &quot;2. 获取路由与元数据&quot; --&gt; YB_Master_Layer</span></span>
<span class="line"><span class="__shiki_140thh">    YB_Master_Layer -- &quot;3. 返回Tablet位置信息&quot; --&gt; YB_TServer_Layer</span></span>
<span class="line"><span class="__shiki_140thh">    YB_TServer_Layer -- &quot;4. 读写相应Tablet数据&quot; --&gt; DocDB_Storage</span></span>
<span class="line"><span class="__shiki_140thh">    DocDB_Storage -- &quot;Raft共识复制&quot; --&gt; DocDB_Storage</span></span></code></pre></div><p>上图清晰地揭示了YugabyteDB的“两层架构”本质：<strong>YB-TServer层</strong>负责处理SQL计算与数据访问，而<strong>YB-Master层</strong>作为集群的大脑进行元数据管理与全局协调。数据最终通过Raft协议，在底层的DocDB分布式存储引擎中以分片（Tablet）形式可靠存储。</p><h2 id="二、架构组件深度解析" tabindex="-1">二、架构组件深度解析 <a class="header-anchor" href="#二、架构组件深度解析" aria-label="Permalink to &quot;二、架构组件深度解析&quot;">​</a></h2><h3 id="_2-1-yb-master-集群的-大脑-与协调者" tabindex="-1">2.1 YB-Master：集群的“大脑”与协调者 <a class="header-anchor" href="#_2-1-yb-master-集群的-大脑-与协调者" aria-label="Permalink to &quot;2.1 YB-Master：集群的“大脑”与协调者&quot;">​</a></h3><p>YB-Master是集群的<strong>系统目录（System Catalog）和协调中心</strong>，但其设计精巧，避免了成为性能瓶颈。</p><ul><li><p><strong>核心职责</strong>：</p><ul><li><strong>元数据管理</strong>：存储所有表、Tablet（数据分片）、副本的位置等元数据。这些元数据本身也通过Raft协议在多个YB-Master实例间复制，确保高可用。</li><li><strong>负载均衡与调度</strong>：持续监控集群状态，根据节点负载、位置感知（如跨可用区、跨区域部署）和用户定义的放置策略，自动执行Tablet副本的拆分、合并与迁移，实现数据分布的动态优化。</li><li><strong>分布式事务协调</strong>：作为<strong>时间戳权威（Timestamp Authority）</strong>，提供严格单调递增的混合逻辑时钟（Hybrid Logical Clock， HLC），为所有分布式事务提供全局一致的时间戳，这是实现一致性快照和MVCC的基础。</li><li><strong>DDL操作协调</strong>：协调如创建/删除表、修改Schema等DDL语句，确保元数据变更在集群内一致生效。</li></ul></li><li><p><strong>关键设计</strong>：YB-Master采用<strong>领导者-追随者（Leader-Follower）</strong> 架构，通过Raft协议保证元数据的高可用和强一致性。客户端通常只与Leader Master交互，但其负载极轻，不参与数据读写路径，因此不会成为性能瓶颈。</p></li></ul><h3 id="_2-2-yb-tserver-数据存储与查询处理的-躯干" tabindex="-1">2.2 YB-TServer：数据存储与查询处理的“躯干” <a class="header-anchor" href="#_2-2-yb-tserver-数据存储与查询处理的-躯干" aria-label="Permalink to &quot;2.2 YB-TServer：数据存储与查询处理的“躯干”&quot;">​</a></h3><p>YB-TServer是<strong>有状态</strong>的节点，负责实际的数据存储和SQL查询处理，是工作负载的主要承担者。</p><ul><li><p><strong>核心职责</strong>：</p><ul><li><strong>数据存储与复制</strong>：每个YB-TServer托管多个Tablet（数据分片）。每个Tablet作为一个Raft组，将其数据复制到集群中的其他YB-TServer上，默认复制因子为3，提供高可用和持久性。</li><li><strong>SQL查询处理（YSQL）</strong>：运行基于PostgreSQL源代码修改的<strong>YSQL服务</strong>。它完全理解PostgreSQL协议和语法，负责SQL的解析、查询优化（基于成本的优化器）和分布式执行计划的生成与执行。</li><li><strong>NoSQL API处理（YCQL）</strong>：提供与Apache Cassandra兼容的YCQL API，用于键值对和宽表操作。</li><li><strong>事务管理</strong>：在节点级别执行分布式事务的两阶段提交（2PC），并与YB-Master协同确保ACID属性。</li></ul></li><li><p><strong>关键设计</strong>：计算与存储<strong>紧耦合但在逻辑上分离</strong>。SQL层（YSQL）与底层的DocDB存储引擎通过清晰的API交互，这种设计既保证了PostgreSQL生态的完整兼容性，又受益于分布式存储的弹性与可靠性。</p></li></ul><h3 id="_2-3-docdb-分布式文档存储引擎" tabindex="-1">2.3 DocDB：分布式文档存储引擎 <a class="header-anchor" href="#_2-3-docdb-分布式文档存储引擎" aria-label="Permalink to &quot;2.3 DocDB：分布式文档存储引擎&quot;">​</a></h3><p>DocDB是YugabyteDB自主研发的<strong>高性能、强一致的分布式文档存储引擎</strong>，是架构的基石。</p><ul><li><strong>数据模型</strong>：本质上是一个<strong>全局有序、分片的Key-Value存储</strong>。它将SQL表中的每一行数据，根据主键编码成一个或多个KV对进行存储。这种设计天然支持水平分片（Sharding）。</li><li><strong>Raft共识协议</strong>：<strong>每个Tablet副本都是一个Raft状态机</strong>。所有写入操作都必须由Tablet的Raft Leader处理，并复制到多数派（Quorum）Follower后才会确认提交，这为每个分片提供了<strong>CP（一致性和分区容错性）</strong> 保证。Raft组负责Leader选举、日志复制和成员变更。</li><li><strong>LSM-Tree存储</strong>：底层使用<strong>RocksDB</strong>作为单机存储引擎。RocksDB基于LSM-Tree（日志结构合并树），具有出色的写入吞吐能力。数据被组织成SSTable文件，并辅以Bloom过滤器等结构加速读取。</li><li><strong>分布式事务与MVCC</strong>：在KV级别实现多版本并发控制（MVCC）。每个修改都带有一个由YB-Master分配的时间戳。读取操作使用快照时间戳，可以访问到特定时间点之前已提交的数据版本，从而实现无锁读取和一致性快照隔离。</li></ul><h2 id="三、关键技术实现机制" tabindex="-1">三、关键技术实现机制 <a class="header-anchor" href="#三、关键技术实现机制" aria-label="Permalink to &quot;三、关键技术实现机制&quot;">​</a></h2><h3 id="_3-1-数据分片与分布" tabindex="-1">3.1 数据分片与分布 <a class="header-anchor" href="#_3-1-数据分片与分布" aria-label="Permalink to &quot;3.1 数据分片与分布&quot;">​</a></h3><p>YugabyteDB通过两种策略实现数据的水平分片，以支持海量数据：</p><ul><li><strong>哈希分片（Hash Sharding）</strong>：使用主键的哈希值来确定数据归属的Tablet。这种方式能将数据<strong>均匀分布</strong>到所有节点，是实现高写入吞吐量的理想选择，尤其适用于时序数据或无需范围查询的场景。</li><li><strong>范围分片（Range Sharding）</strong>：根据主键的实际值范围进行分片。这种方式能<strong>高效支持主键的范围查询</strong>，因为相邻键的数据很可能位于同一Tablet或相邻Tablet。适用于需要按时间范围或字母顺序扫描的场景。 用户可以在建表时通过 <code>USING HASH</code> 或 <code>SPLIT AT</code> 等语法指定分片策略。</li></ul><h3 id="_3-2-分布式事务与一致性" tabindex="-1">3.2 分布式事务与一致性 <a class="header-anchor" href="#_3-2-分布式事务与一致性" aria-label="Permalink to &quot;3.2 分布式事务与一致性&quot;">​</a></h3><p>这是YugabyteDB的核心优势，它在分布式环境下提供了与PostgreSQL相当的一致性级别（默认<strong>可序列化快照隔离-SSI</strong>）。</p><ol><li><strong>时间戳与MVCC</strong>：如前所述，HLC和时间戳是MVCC的基石，定义了数据的全局顺序。</li><li><strong>两阶段提交（2PC）</strong>：对于跨多个Tablet（即跨分片）的写事务，YSQL层作为协调者，使用2PC协议确保原子性。</li><li><strong>冲突解决与锁</strong>： <ul><li><strong>乐观并发控制（OCC）</strong>：在提交阶段检测读写冲突，若冲突则中止并重试事务。</li><li><strong>行级锁</strong>：通过“意向锁”在存储层实现行级锁定，防止写写冲突。</li></ul></li><li><strong>读写路径</strong>： <ul><li><strong>写路径</strong>：SQL -&gt; 识别涉及Tablet -&gt; 向各Tablet Leader发起Raft复制 -&gt; 2PC协调 -&gt; 提交。</li><li><strong>读路径</strong>：SQL -&gt; 识别涉及Tablet -&gt; 向Tablet Leader或最近Follower（若启用 follower reads）发送读请求 -&gt; 根据读时间戳从MVCC历史中返回数据。</li></ul></li></ol><h3 id="_3-3-查询处理与优化" tabindex="-1">3.3 查询处理与优化 <a class="header-anchor" href="#_3-3-查询处理与优化" aria-label="Permalink to &quot;3.3 查询处理与优化&quot;">​</a></h3><p>YSQL的查询引擎经过深度改造，能够生成高效的分布式执行计划。</p><ul><li><strong>分布式执行计划</strong>：优化器会将一个复杂的SQL查询（如多表JOIN、聚合）分解为多个可以在不同Tablet上并行执行的子任务。例如，它可能将 <code>WHERE</code> 子句的过滤条件“下推”到存储层，在数据本地进行过滤，大幅减少网络传输的数据量。</li><li><strong>Colocation（并置）</strong>：对于需要频繁JOIN的小表或相关表组，可以将其放置在相同的分片组中，使JOIN操作能在本地完成，极大提升关联查询性能。</li></ul><h3 id="_3-4-容错、扩展与运维" tabindex="-1">3.4 容错、扩展与运维 <a class="header-anchor" href="#_3-4-容错、扩展与运维" aria-label="Permalink to &quot;3.4 容错、扩展与运维&quot;">​</a></h3><ul><li><strong>自动故障恢复</strong>：任何一个YB-TServer或YB-Master节点故障，其承载的Tablet或元数据副本都会在其他健康节点上自动重新复制，恢复至用户设定的复制因子。Raft协议能自动选举新的Leader，整个过程对应用透明。</li><li><strong>弹性水平扩展</strong>：通过简单添加新的YB-TServer节点，集群即可实现水平扩展。YB-Master会自动将部分Tablet迁移到新节点，实现数据和负载的均匀分布。此过程<strong>在线进行，无需停机</strong>。</li><li><strong>多云/混合云部署</strong>：支持跨多个可用区（AZ）甚至跨不同云提供商（AWS， GCP， Azure）或本地数据中心部署，通过配置合理的副本放置策略（Placement Policy）来满足数据驻留要求和实现异地容灾。</li></ul><h2 id="四、与cockroachdb、tidb的对比分析" tabindex="-1">四、与CockroachDB、TiDB的对比分析 <a class="header-anchor" href="#四、与cockroachdb、tidb的对比分析" aria-label="Permalink to &quot;四、与CockroachDB、TiDB的对比分析&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;"><strong>YugabyteDB</strong></th><th style="text-align:left;"><strong>CockroachDB</strong></th><th style="text-align:left;"><strong>TiDB</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>设计哲学</strong></td><td style="text-align:left;"><strong>两层架构</strong>，深度集成PostgreSQL， 追求极致PG兼容与分布式事务。</td><td style="text-align:left;"><strong>对等节点</strong>架构，自研SQL层，追求全局分布式与地理分区。</td><td style="text-align:left;"><strong>三层架构</strong>，计算（TiDB）、调度（PD）、存储（TiKV）分离，强调HTAP混合负载。</td></tr><tr><td style="text-align:left;"><strong>SQL兼容性</strong></td><td style="text-align:left;"><strong>基于PostgreSQL代码修改（YSQL）</strong>，兼容度极高，支持存储过程、触发器、扩展等。</td><td style="text-align:left;">自研SQL层，语法类似PostgreSQL，但对高级特性支持渐进。</td><td style="text-align:left;">兼容MySQL 5.7+协议和语法，生态迁移友好。</td></tr><tr><td style="text-align:left;"><strong>一致性核心</strong></td><td style="text-align:left;"><strong>YB-Master中心化授时（HLC）</strong> + Tablet Raft组。</td><td style="text-align:left;"><strong>去中心化的混合逻辑时钟（HLC）</strong>，节点间协同。</td><td style="text-align:left;"><strong>PD中心化授时</strong> + TiKV Raft组。</td></tr><tr><td style="text-align:left;"><strong>事务模型</strong></td><td style="text-align:left;">默认<strong>悲观锁</strong>，支持乐观并发控制。</td><td style="text-align:left;">早期默认<strong>乐观锁</strong>，后续增加了悲观锁支持。</td><td style="text-align:left;">默认<strong>悲观锁</strong>（与MySQL一致）。</td></tr><tr><td style="text-align:left;"><strong>扩展性</strong></td><td style="text-align:left;">通过增加YB-TServer水平扩展存储和计算。</td><td style="text-align:left;">增加对等节点实现整体扩展。</td><td style="text-align:left;"><strong>计算（TiDB）和存储（TiKV）可独立横向扩展</strong>，灵活性高。</td></tr><tr><td style="text-align:left;"><strong>关键优势</strong></td><td style="text-align:left;"><strong>PG兼容性、强分布式事务、运维相对简单</strong>。</td><td style="text-align:left;"><strong>卓越的跨地域部署与生存能力、去中心化</strong>。</td><td style="text-align:left;"><strong>成熟的HTAP能力（TiFlash）、活跃的中文社区、云原生集成</strong>。</td></tr></tbody></table><h2 id="五、适用场景与选型建议" tabindex="-1">五、适用场景与选型建议 <a class="header-anchor" href="#五、适用场景与选型建议" aria-label="Permalink to &quot;五、适用场景与选型建议&quot;">​</a></h2><ul><li><p><strong>优先考虑YugabyteDB的场景</strong>：</p><ol><li>现有应用重度依赖<strong>PostgreSQL特性</strong>（如特定扩展、存储过程），希望以最小改造迁移至分布式数据库。</li><li>业务需要<strong>强一致的分布式ACID事务</strong>，且对<strong>低延迟的OLTP</strong>性能有较高要求。</li><li>偏好<strong>相对简洁的运维模型</strong>，两层架构可能比完全对等或三层架构更易理解和管控。</li></ol></li><li><p><strong>可能需要考虑其他方案的场景</strong>：</p><ol><li>需要<strong>强大的实时分析（OLAP）能力</strong>。虽然YugabyteDB支持只读副本，但TiDB的TiFlash列存引擎在HTAP场景上更为成熟。</li><li>业务部署<strong>极度全球化</strong>，对跨大洲的多主写入和极致容灾有超强需求，CockroachDB在该领域有更久的设计积淀。</li><li>技术栈完全围绕<strong>MySQL生态</strong>，且无PostgreSQL使用经验或需求。</li></ol></li></ul><h2 id="六、演进与展望" tabindex="-1">六、演进与展望 <a class="header-anchor" href="#六、演进与展望" aria-label="Permalink to &quot;六、演进与展望&quot;">​</a></h2><p>YugabyteDB持续演进，其方向包括：</p><ul><li><strong>100% PostgreSQL兼容性</strong>：不断缩小与上游PostgreSQL的差距，支持更多扩展和数据类型。</li><li><strong>更强大的HTAP</strong>：增强只读副本的能力，探索列式存储选项，以更好地服务分析查询。</li><li><strong>云原生与Kubernetes</strong>：优化在K8s上的Operator（如YugabyteDB Anywhere）和托管服务体验。</li><li><strong>生态系统集成</strong>：加强与流处理、数据湖等生态系统的连接器。</li></ul><p>希望这份详尽的笔记能帮助你系统性地掌握YugabyteDB分布式SQL的核心架构与设计精髓。如果你对其中任何技术细节（如DocDB的KV编码格式、Raft在故障恢复中的具体流程等）有进一步的兴趣，我们可以继续深入探讨。</p>`,36)])])}const _=s(r,[["render",l]]);export{c as __pageData,_ as default};
